use vstd::prelude::*;

verus! {

fn reverse(a: &[i32]) -> (res: Vec<i32>)
    ensures
        // The result has exactly the same length as the input slice
        res.len() == a.len(),
        // And for each index i, res[i] = a[a.len() - 1 - i]
        forall |i: nat| i < a.len() as nat
            ==> res.index(i) == a[(a.len() - 1 - i as usize)],
{
    let n_usize: usize = a.len();
    // Build a fresh vector and reserve space
    let mut res: Vec<i32> = Vec::new();
    res.reserve(n_usize);

    // We'll push elements one by one in reverse order
    let mut idx: usize = 0;
    while idx < n_usize
        invariant
            // idx is always between 0 and n_usize
            idx <= n_usize,
            // we've pushed exactly idx elements so far
            res.len() == idx,
            // and for each j < idx, res[j] == a[n_usize - 1 - j]
            forall |j: nat| j < idx as nat
                ==> res.index(j) == a[(n_usize - 1 - j as usize)],
        decreases n_usize - idx,
    {
        // pick the next element from the end of `a`
        let v: i32 = a[n_usize - 1 - idx];
        res.push(v);
        idx = idx + 1;
    }

    res
}

} // end of verus! block

